  constructor(
    private sanitizer: DomSanitizer,
    private router: Router,
    private menuCtrl: MenuController,
    public language: SiteLanguageService) {
  }

  toggleAppMenu() {
    this.menuCtrl.toggle('start');
  }

  scrollTo(id: string) {
    const el = document.getElementById(id);
    if (el) {
      el.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  }

  ngAfterViewInit(): void {
    this.animateCounter();
    this.generateParticles();
  }

  animateCounter(): void {
    const target = this.allowedTools.length;
    const duration = 1800;
    const steps = 60;
    const increment = target / steps;
    let current = 0;
    const timer = setInterval(() => {
      current += increment;
      if (current >= target) {
        this.animatedToolCount = target;
        clearInterval(timer);
      } else {
        this.animatedToolCount = Math.floor(current);
      }
    }, duration / steps);
  }

  generateParticles(): void {
    for (let i = 0; i < 20; i++) {
      this.particles.push({
        x: Math.random() * 100,
        y: Math.random() * 100,
        size: Math.random() * 4 + 2,
        delay: Math.random() * 5,
        duration: Math.random() * 10 + 15,
      });
    }
  }

  getCategoryIcon(category: string): string {
    const icons: Record<string, string> = {
      'همه ابزارها': 'apps-outline',
      'فارسی و سوادآموزی': 'book-outline',
      'ریاضی و اعداد': 'calculator-outline',
      'مدیریت کلاس': 'people-outline',
      'بازی و خلاقیت': 'color-palette-outline',
    };
    return icons[category] || 'grid-outline';
  }

  getCategoryCount(category: string): number {
    if (category === 'همه ابزارها') { return this.allowedTools.length; }
    return this.allowedTools.filter(t => t.category === category).length;
  }

  doRefresh(event) {

    setTimeout(() => {

      location.reload();
      event.target.complete();
    }, 2000);
  }

  ionViewWillEnter() {

    this.login = GAccount.IsLoggedIn();
  }

  goTop() {
    this.content.scrollToTop(3000);
  }

  forwardUrl(url: string) {
    window.location.href = url;
  }

  isAndroid(): boolean {

    return G.IsAndroid;
  }

  isAdmin(): boolean {

    return GAccount.IsAdminActive();
  }

  ngOnInit(): void {

    this.instagram = G.Instagram;
    this.twiter = G.Twiter;
    this.facebook = G.Facebook;
    this.telegram = G.Telegram;
    this.youtube = G.Youtube;
    this.pinterest = G.Pinterest;
    this.linkedin = G.Linkedin;
    this.twitch = G.Twitch;
    this.aparat = G.Aparat;
    this.discord = G.Discord;
    this.tunerPlusVideo = G.TunerPlusVideo;
  }

  onNavigate(url: string) {

    this.router.navigateByUrl(url);
  }

  selectCategory(category: string): void {
    this.activeCategory = category;
  }

  private get allowedTools(): TunerPlusTool[] {
    return this.tools.filter(tool => !tool.hidden && (!tool.admin || this.isAdmin()));
  }

  get visibleTools(): TunerPlusTool[] {
    let list = this.activeCategory === 'همه ابزارها'
      ? this.allowedTools
      : this.allowedTools.filter(tool => tool.category === this.activeCategory);
    if (this.toolFilterQuery && this.toolFilterQuery.trim()) {
      const q = this.toolFilterQuery.trim().toLowerCase();
      list = list.filter(t => (t.title && t.title.toLowerCase().includes(q)) || (t.subtitle && t.subtitle.toLowerCase().includes(q)));
    }
    return list;
  }

  get featuredTools(): TunerPlusTool[] {
    return this.allowedTools.filter(tool => tool.featured);
  }

  categoryName(category: string): string {
    if (this.language.current === 'fa') { return category; }
    const keys: Record<string, string> = {
      'همه ابزارها': 'all', 'فارسی و سوادآموزی': 'persianLiteracy', 'ریاضی و اعداد': 'mathNumbers',
      'مدیریت کلاس': 'classManagement', 'بازی و خلاقیت': 'gamesCreativity'
    };
    const key = 'tunerPlus.category.' + keys[category];
    const translated = this.language.text(key);
    return translated === key ? category : translated;
  }

  toolText(tool: TunerPlusTool, field: 'title' | 'subtitle'): string {
    if (this.language.current === 'fa') { return tool[field]; }
    const key = 'tunerPlus.tool.' + tool.route.split('/').pop().toLowerCase() + '.' + field;
    const translated = this.language.text(key);
    return translated === key ? tool[field] : translated;
  }

  onCancel() {
    this.showSearchbar = false;
  }

  search() {

    if (this.queryText == null || this.queryText.length < 1) {
      return;
    }

    this.router
      .navigate(
        ['Home', 'Search'],
        {
          queryParams:
          {
            title: this.queryText
          }
        });
  }

  async goLogin() {

    for (let i = 0; i < localStorage.length; i++) {
      if (localStorage.key(i) === 'returnUrl') {
        localStorage.removeItem('returnUrl');
      }
    }

    localStorage.setItem('returnUrl', this.language.url('/TunerPlus'));

    // this.router.navigateByUrl(Urls.AccountUrl);
  }

  checkURL() {
    const url = 'https://www.aparat.com/video/video/embed/videohash/' +
      this.tunerPlusVideo +
      '/vt/frame';

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }

  checkVideoUrl() {
    const url = 'https://www.aparat.com/v/' +
      this.tunerPlusVideo;

    return this.sanitizer.bypassSecurityTrustResourceUrl(url);
  }
